"""Diameter of Binary Tree — depth-first, tracking the best split at each node.

A path through a node costs leftDepth + rightDepth edges; the recursion returns
the depth upward while recording the best combination seen.

Time: O(n)   Space: O(h)
"""
if "TreeNode" not in globals():
    class TreeNode:
        def __init__(self, val=0, left=None, right=None):
            self.val = val
            self.left = left
            self.right = right


class Solution:
    def diameterOfBinaryTree(self, root) -> int:
        best = 0

        def depth(node) -> int:
            nonlocal best
            if not node:
                return 0
            left, right = depth(node.left), depth(node.right)
            best = max(best, left + right)
            return 1 + max(left, right)

        depth(root)
        return best
